//! Case- and accent-insensitive folding used by search, ported from `fold`/`isWordChar` in
//! `src/search.zig`. The table is generated by `tests/generate_fold_table.py` (the same script
//! and data as the Zig table), so both implementations fold identically.

use crate::fold_table::ENTRIES;

/// Lowercase base letter for case- and accent-insensitive comparison. Code points absent from
/// the table (and non-letters) fold to themselves.
pub fn fold(cp: u32) -> u32 {
    if cp < 0x80 {
        return (cp as u8).to_ascii_lowercase() as u32;
    }
    match ENTRIES.binary_search_by_key(&cp, |&(from, _)| from) {
        Ok(i) => ENTRIES[i].1,
        Err(_) => cp,
    }
}

/// Letters and digits of the scripts Kata carries, after folding.
pub fn is_word_char(folded: u32) -> bool {
    match folded {
        0x30..=0x39 | 0x61..=0x7a => true,
        0xdf..=0x24f => folded != 0xf7,
        0x370..=0x3ff => !matches!(folded, 0x375 | 0x37e | 0x384 | 0x385 | 0x387),
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // Ported from the Zig test "folding ignores case, accents, and final sigma".
    #[test]
    fn ignores_case_accents_and_final_sigma() {
        assert_eq!(fold('A' as u32), 'a' as u32);
        assert_eq!(fold(0x1F71), 0x03B1); // ά
        assert_eq!(fold(0x03C2), 0x03C3); // ς
        assert_eq!(fold(0x039B), 0x03BB); // Λ
        assert_eq!(fold(0x00C9), 'e' as u32); // É
        assert_eq!(fold(0x2019), 0x2019);
    }

    #[test]
    fn table_is_sorted_and_unique() {
        assert!(ENTRIES.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn word_characters() {
        assert!(is_word_char('x' as u32));
        assert!(is_word_char('7' as u32));
        assert!(is_word_char(0x3b1));
        assert!(!is_word_char(0x387));
        assert!(!is_word_char(0xf7));
        assert!(!is_word_char(' ' as u32));
        assert!(!is_word_char(0x2019));
    }
}
